  useEffect(()=>{void applyLogoTheme(catalog?.logoData||'',catalog?.brandColor||'');return()=>{void applyLogoTheme('')}},[catalog?.logoData,catalog?.brandColor])
  async function enterGuest(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');try{const response=await fetch(`${api}/v1/customer-portal/guest`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId,name,mode})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not open bookings.');sessionStorage.setItem(tokenKey,data.accessToken);setToken(data.accessToken)}catch(e){setError(e instanceof Error?e.message:'Could not open bookings.')}finally{setBusy(false)}}
  async function signIn(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');try{const response=await fetch(`${api}/v1/customer-portal/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId,username,password})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Sign-in failed.');sessionStorage.setItem(tokenKey,data.accessToken);setToken(data.accessToken)}catch(e){setError(e instanceof Error?e.message:'Sign-in failed.')}finally{setBusy(false)}}
  async function book(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');setMessage('');const key=`${requestKey}-ticket`,requestId=localStorage.getItem(key)||crypto.randomUUID();localStorage.setItem(key,requestId);try{const response=await fetch(`${api}/v1/customer-portal/hospitality/bookings`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({requestId,type:mode,roomId,guestCount:Number(roomGuests),eventId,ticketTypeId,promoCode,attendeeAnswers,email,checkIn,checkOut,phone})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not complete this booking.');localStorage.removeItem(key);const messagesEnabled=catalog?.guestMessagingEnabled===true;setMessage(mode==='hotel'?`Stay reserved.${messagesEnabled?' A confirmation and reminder will be sent to your email.':''}`:data.booking?.status==='waitlisted'?'You are on the event waitlist. The venue will contact you if a place becomes available.':`Admission reserved at ${price(data.booking?.admissionPrice||0)}.${messagesEnabled?' A confirmation and reminder will be sent to your email.':''}`);await Promise.all([loadBookings(token),loadCatalog(checkIn,checkOut)]);if(mode==='nightlife'&&data.booking?.status==='expected'&&data.booking?.ticketInvoiceId&&catalog?.onlinePaymentEnabled){setBusy(true);try{await startCheckout(data.booking.ticketInvoiceId)}catch(paymentError){setError(paymentError instanceof Error?`Admission is reserved. ${paymentError.message} You can retry payment from Your bookings.`:'Admission is reserved, but online checkout did not start. Retry from Your bookings.');setBusy(false)}}}catch(e){setError(e instanceof Error?e.message:'Could not complete this booking.')}finally{setBusy(false)}}
