  async function payInvoice(event:React.FormEvent,invoiceId:string){event.preventDefault();setBusy(true);setError('');setMessage('');try{await startCheckout(invoiceId)}catch(e){setError(e instanceof Error?e.message:'Could not start invoice payment.');setBusy(false)}}
  async function bookTable(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');setMessage('');const key=`${requestKey}-table`,requestId=localStorage.getItem(key)||crypto.randomUUID();localStorage.setItem(key,requestId);try{const response=await fetch(`${api}/v1/customer-portal/hospitality/table-reservations`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({requestId,eventId,tableId,tablePackageId,guests:Number(tableGuests),phone,email})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not reserve this table.');localStorage.removeItem(key);setMessage(`Table reserved.${tablePackageId?` ${selectedPackage?.name||'Service package'} added; minimum spend is tracked on the event bill.`:''}${catalog?.guestMessagingEnabled?' A confirmation and reminder will be sent to your email.':''}`);await loadBookings(token)}catch(e){setError(e instanceof Error?e.message:'Could not reserve this table.')}finally{setBusy(false)}}
