  if(!token)return <main className="portal-login"><section className="portal-login-card"><a className="portal-brand" href={`/?customer=${encodeURIComponent(businessId)}&catalog=${mode}`}><img src={catalog?.logoData||'/logo.png'} alt=""/><span><strong>{catalog?.businessName||'Guest services'}</strong><small>Stockroom Business App</small></span></a><h1>{mode==='hotel'?'Book a stay':'Book event admission'}</h1><p>Enter your name and phone to continue as a guest, or sign in to connect this booking to your customer account and wallet.</p><form className="portal-form" onSubmit={enterGuest}><label>Guest name<input required maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></label><label>Phone number<input required minLength={6} maxLength={80} value={phone} onChange={e=>setPhone(e.target.value)}/></label><button className="portal-btn" disabled={busy||!online}>Continue as guest</button></form><h2>Customer account</h2><form className="portal-form" onSubmit={signIn}><label>Username<input autoComplete="username" required value={username} onChange={e=>setUsername(e.target.value)}/></label><label>Password<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="portal-btn secondary" disabled={busy||!online}>Sign in</button></form>{error&&<div className="portal-alert error" role="alert">{error}</div>}</section></main>
